/bin/bash -lc "cd /workspace && python3 - <<'PYEOF'
import io, json, urllib.error, sys
import openai_client as oc

captured = {}

class FakeResp(io.BytesIO):
    def __enter__(self): return self
    def __exit__(self, *a): return False

def fake_urlopen(req, timeout=None):
    captured.update(url=req.full_url, method=req.get_method(),
                    headers=dict(req.headers), body=json.loads(req.data.decode()))
    return FakeResp(json.dumps({
        \"id\": \"resp_1\", \"output\": [
            {\"type\": \"message\", \"content\": [{\"type\": \"output_text\", \"text\": \"Hello there.\"}]}
        ]}).encode())

oc.urllib.request.urlopen = fake_urlopen
c = oc.OpenAIClient(api_key=\"sk-test-secret\")
print(\"ask ->\", c.ask(\"hi\", model=\"gpt-5-preview\"))
print(\"store default ->\", captured[\"body\"][\"store\"])
print(\"auth header not in repr ->\", repr(c))
assert \"sk-test-secret\" not in repr(c)

# streaming path
lines = [
    b'data: {\"type\":\"response.output_text.delta\",\"delta\":\"Hel\"}\\n\\n',
    b'data: {\"type\":\"response.output_text.delta\",\"delta\":\"lo\"}\\n\\n',
    b'data: [DONE]\\n\\n',
]
class FakeStream:
    def __iter__(self): return iter(lines)
    def close(self): pass
def fake_stream_urlopen(req, timeout=None):
    captured.update(url=req.full_url, body=json.loads(req.data.decode()))
    return FakeStream()
oc.urllib.request.urlopen = fake_stream_urlopen
print(\"stream ->\", \"\".join(oc.iter_events(c.stream_response(\"hi\", model=\"gpt-5-preview\"))))
print(\"stream body ->\", captured[\"body\"])

# API error path
def fake_http_error(req, timeout=None):
    raise urllib.error.HTTPError(captured[\"url\"], 401, \"Unauthorized\", {},
        io.BytesIO(json.dumps({\"error\": {\"message\": \"Incorrect API key\", \"type\": \"invalid_request_error\", \"code\": \"invalid_api_key\"}}).encode()))
oc.urllib.request.urlopen = fake_http_error
try:
    c.ask(\"hi\", model=\"x\")
except oc.OpenAIAPIError as e:
    print(\"api error ->\", e.status, e.type, e.code, \"|\", e)

# transport error path
def fake_url_error(req, timeout=None):
    raise urllib.error.URLError(\"dns failure\")
oc.urllib.request.urlopen = fake_url_error
try:
    c.ask(\"hi\", model=\"x\")
except oc.OpenAITransportError as e:
    print(\"transport error ->\", e)

# missing model
captured.clear()
try:
    c.ask(\"hi\")
except oc.OpenAIError as e:
    print(\"no model ->\", e)
print(\"ALL OK\")
PYEOF"

